"use strict";document.addEventListener("DOMContentLoaded",()=>{const cards=[...document.querySelectorAll("[data-revision-card]")],revealAll=document.querySelector("[data-reveal-all]"),reset=document.querySelector("[data-reset-cards]");function setCard(card,open){const trigger=card.querySelector(".revision-card__trigger"),answer=card.querySelector(".revision-card__answer"),hint=card.querySelector(".revision-card__hint");card.dataset.open=String(open),trigger.setAttribute("aria-expanded",String(open)),answer.hidden=!open,hint.textContent=open?"Masquer la réponse":"Afficher la réponse"}cards.forEach(card=>{const trigger=card.querySelector(".revision-card__trigger");setCard(card,!1),trigger.addEventListener("click",()=>setCard(card,trigger.getAttribute("aria-expanded")!=="true"))}),revealAll&&revealAll.addEventListener("click",()=>cards.forEach(card=>setCard(card,!0))),reset&&reset.addEventListener("click",()=>{cards.forEach(card=>setCard(card,!1)),cards[0]?.querySelector(".revision-card__trigger")?.focus()})});
